 let key='',limit=24,total=0,last=[];
 const paging=window.RentcamCatalogPaging={select(ordered){const next=location.pathname+location.search;if(next!==key){key=next;limit=24}const u=new URLSearchParams(location.search),min=u.get('minPrice'),max=u.get('maxPrice');last=ordered.filter(p=>{if(min===null&&max===null)return true;const html=typeof window.pc==='function'?window.pc(p):'',prices=[...html.matchAll(/Rp\s*([\d.,]+)/g)],price=prices.length?Number(prices.at(-1)[1].replace(/[.,]/g,'')):Number(p.price)||0;return (min===null||price>=Number(min))&&(max===null||price<=Number(max))});total=last.length;return last.slice(0,limit)},footer(){if(!total)return '';const shown=Math.min(limit,total);return '<div class="rc-catalog-more"><p role="status">Menampilkan '+shown+' dari '+total+' produk</p>'+(shown<total?'<button type="button" data-catalog-more>Tampilkan lebih banyak <span aria-hidden="true">＋</span></button>':'<span>Semua produk sudah ditampilkan</span>')+'</div>'}};
